/* =========================================================================
   SAFE STORAGE & CLIENT-SIDE RELATIONAL STORE
========================================================================= */
const STORAGE_KEY = "wdki_relational_db_v2";
let memoryFallback = null;

function safeReadStorage() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return memoryFallback;
  }
}

function safeWriteStorage(data) {
  memoryFallback = data;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    // Fallback already stored in memoryFallback
  }
}

// Simple deterministic salted hash for client-side local auth (backend uses PBKDF2-HMAC-SHA256)
function clientHashPassword(pw, salt) {
  let h = 2166136261;
  const str = salt + "::" + pw + "::wdki";
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return "sha_client$" + salt + "$" + (h >>> 0).toString(16);
}

