function generateTextCode(name, idHint) {
  const prefix = String(name || "ITEM").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "ITEM";
  const suffix = idHint != null ? String(idHint).padStart(2, "0") : Math.random().toString(36).slice(2, 5).toUpperCase();
  return prefix + "-" + suffix;
}

let DB = safeReadStorage() || createInitialDatabase();
(DB.users || []).forEach(u => {
  if (u.motor_mode === undefined) u.motor_mode = false;
  if (u.dwell_click === undefined) u.dwell_click = false;
  if (u.tap_debounce === undefined) u.tap_debounce = false;
  if (u.reduced_motion === undefined) u.reduced_motion = false;
  if (u.colorblind_mode === undefined) u.colorblind_mode = false;
  if (u.color_vision_mode === undefined) u.color_vision_mode = u.colorblind_mode ? "complete" : "none";
  if (u.auto_read_screen === undefined) u.auto_read_screen = false;
});
(DB.objects || []).forEach(o => { if (!o.text_code) o.text_code = generateTextCode(o.name, o.id); });
(DB.ar_markers || []).forEach(m => {
  if (!m.text_code) {
    const obj = (DB.objects || []).find(o => o.id === m.object_id);
    m.text_code = obj ? obj.text_code : m.marker_reference;
  }
});
safeWriteStorage(DB);

function saveDB() {
  safeWriteStorage(DB);
}

function nextId() {
  DB.nextId = (DB.nextId || 100) + 1;
  return DB.nextId;
}

