function nudgeRoom(roomId, dx, dy) {
  const room = DB.rooms.find(r => r.id === Number(roomId));
  if (!room) return;
  room.x = Math.max(8, Math.min(760 - room.width, room.x + dx));
  room.y = Math.max(8, Math.min(400 - room.height, room.y + dy));
  saveDB();
  render();
}

