async function startBurstAutoTrain(objectId) {
  const vid = document.getElementById("arVideo");
  if (!state.arCameraActive || !vid || !vid.videoWidth) {
    showToast("Tap 'Start AR Camera' first, hold the object in the center box, then tap Auto-Train.", "info");
    return;
  }
  if (state.arAutoTraining) return;
  state.arAutoTraining = true;
  const obj = getActiveObjects().find(o => o.id === Number(objectId));
  speakText(`Training AI on ${obj ? obj.name : "your object"}. Slowly rotate it inside the center box.`);
  let captured = 0;
  for (let i = 0; i < 10; i++) {
    if (!state.arCameraActive) break;
    const ok = await trainSampleFromSource(objectId, vid);
    if (ok) captured++;
    const cnt = state.arTrainedCounts[String(objectId)] || 0;
    updateARLivePromptDOM(`Training AI: ${captured}/10 angles captured (${cnt} total)`, false);
    await new Promise(r => setTimeout(r, 280));
  }
  state.arAutoTraining = false;
  const total = state.arTrainedCounts[String(objectId)] || 0;
  showToast(`AI trained on "${obj ? obj.name : "object"}" with ${total} samples!`);
  speakText(`Training complete! The AI now recognizes your ${obj ? obj.name : "object"} with ${total} angles.`);
  const cntEl = document.getElementById("trainSampleCountBadge");
  if (cntEl) cntEl.textContent = `${total} trained samples`;
}

function resetTrainedSamplesForObject(objectId) {
  if (state.arKnnClassifier) {
    try { state.arKnnClassifier.clearClass(String(objectId)); } catch (e) {}
    state.arTrainedCounts = state.arKnnClassifier.getClassExampleCount() || {};
    saveKnnToStorage();
  }
  showToast("Cleared custom AI training samples for this object.", "info");
  render();
}

async function runCalibratedInference(sourceEl, isLiveFrame) {
  const objs = getActiveObjects();
  const candidates = [];
  let bestKnnObj = null;
  let bestKnnConf = 0;
  let knnMargin = 0;

  // 1. Custom Trained KNN Classifier on Center Crop (Highest Priority — trained on user's exact splints/orthotics/items!)
  if (state.arKnnClassifier && state.arMobileNetModel && state.arKnnClassifier.getNumClasses() > 0) {
    try {
      const crop = getCenterCropCanvas(sourceEl);
      const act = state.arMobileNetModel.infer(crop, true);
      const kVal = Math.min(5, Math.max(1, Object.values(state.arTrainedCounts).reduce((a, b) => a + b, 0)));
      const res = await state.arKnnClassifier.predictClass(act, kVal);
      if (act.dispose) act.dispose();
      const sorted = Object.entries(res.confidences || {}).sort((a, b) => b[1] - a[1]);
      if (sorted.length > 0) {
        const [topId, topScore] = sorted[0];
        const secondScore = sorted[1] ? sorted[1][1] : 0;
        knnMargin = topScore - secondScore;
        const matchedObj = objs.find(o => String(o.id) === String(topId));
        if (matchedObj) {
          bestKnnObj = matchedObj;
          bestKnnConf = topScore;
          candidates.push({ label: `${matchedObj.name} [${matchedObj.text_code}] (Trained AI)`, score: topScore, object: matchedObj, source: "knn" });
        }
      }
    } catch (e) {}
  }

  // 2. High-Accuracy COCO-SSD (Bounding Boxes)
  let cocoDetections = [];
  if (state.arCocoModel) {
    try {
      const preds = await state.arCocoModel.detect(sourceEl);
      cocoDetections = (preds || []).filter(p => p.score >= Math.max(0.52, state.arConfidenceThreshold - 0.14));
      cocoDetections.forEach(p => {
        const m = matchDetectionToSavedObject(p.class);
        candidates.push({
          label: m ? `${m.name} [${m.text_code}] (COCO-SSD)` : `${p.class} (COCO-SSD)`,
          score: p.score, object: m, rawClass: p.class, bbox: p.bbox, source: "coco"
        });
      });
    } catch (e) {}
  }

  // 3. Full MobileNet v2 (1,000 classes) on Center Crop (ignores messy room background!)
  let mnTop = null;
  if (state.arMobileNetModel) {
    try {
      const crop = getCenterCropCanvas(sourceEl);
      const preds = await state.arMobileNetModel.classify(crop, 3);
      if (preds && preds.length) {
        mnTop = preds[0];
        const clean = mnTop.className.split(",")[0].trim();
        const m = matchDetectionToSavedObject(mnTop.className);
        candidates.push({
          label: m ? `${m.name} [${m.text_code}] (MobileNet)` : `${clean} (MobileNet)`,
          score: mnTop.probability, object: m, rawClass: clean, source: "mobilenet"
        });
      }
    } catch (e) {}
  }

  candidates.sort((a, b) => b.score - a.score);
  if (isLiveFrame) updateCandidatesDOM(candidates);

  // Calibrated Decision Rule:
  // Prefer Trained KNN if confidence >= threshold AND clear margin >= 0.15 (or single class with >= 3 samples)
  const numClasses = state.arKnnClassifier ? state.arKnnClassifier.getNumClasses() : 0;
  const sampleCnt = bestKnnObj ? (state.arTrainedCounts[String(bestKnnObj.id)] || 0) : 0;
  const knnReliable = bestKnnObj && bestKnnConf >= state.arConfidenceThreshold && (numClasses === 1 ? sampleCnt >= 3 : knnMargin >= 0.15);

  if (knnReliable) {
    return { matchedObj: bestKnnObj, label: bestKnnObj.name, score: bestKnnConf, source: "Trained AI", cocoDetections, candidates };
  }
  const strongCoco = cocoDetections.find(p => p.score >= state.arConfidenceThreshold);
  if (strongCoco) {
    const m = matchDetectionToSavedObject(strongCoco.class);
    return { matchedObj: m, label: m ? m.name : strongCoco.class, score: strongCoco.score, source: "COCO-SSD", bbox: strongCoco.bbox, cocoDetections, candidates };
  }
  if (mnTop && mnTop.probability >= Math.max(0.55, state.arConfidenceThreshold - 0.1)) {
    const clean = mnTop.className.split(",")[0].trim();
    const m = matchDetectionToSavedObject(mnTop.className);
    return { matchedObj: m, label: m ? m.name : clean, score: mnTop.probability, source: "MobileNet v2", cocoDetections, candidates };
  }
  return { matchedObj: null, label: null, score: 0, source: "uncertain", cocoDetections, candidates };
}

