function simulateARObjectAndCodeDetect(objectId) {
  const obj = getActiveObjects().find(o => o.id === Number(objectId));
  if (!obj) return;
  state.arTargetObjectId = obj.id;
  const code = obj.text_code || generateTextCode(obj.name, obj.id);
  state.arDetectedObject = {
    existingObjectId: obj.id,
    name: obj.name,
    category: obj.category,
    textCode: code,
    roomId: obj.room_id,
    storageLocation: obj.storage_location,
    snapshotUrl: obj.image_url || SVG_PLACEHOLDERS.defaultObj,
    sourceBadge: "Image + Code Detected"
  };
  render();
  speakText(`Detected ${obj.name}, code ${code}. Usually kept in ${getRoomName(obj.room_id)} at ${obj.storage_location}.`);
}

function captureCurrentARFrameForSave() {
  const vid = document.getElementById("arVideo");
  let snap = SVG_PLACEHOLDERS.defaultObj;
  if (vid && vid.videoWidth) {
    const c = document.createElement("canvas");
    c.width = 480;
    c.height = Math.round(480 * (vid.videoHeight / vid.videoWidth));
    c.getContext("2d").drawImage(vid, 0, 0, c.width, c.height);
    snap = c.toDataURL("image/jpeg", 0.82);
  }
  const topCand = state.arTopCandidates[0];
  const rooms = getActiveRooms();
  const targetObj = getActiveObjects().find(o => o.id === Number(state.arTargetObjectId));

  if (topCand && topCand.object && topCand.score >= state.arConfidenceThreshold) {
    const m = topCand.object;
    state.arDetectedObject = {
      existingObjectId: m.id, name: m.name, category: m.category,
      textCode: m.text_code || generateTextCode(m.name, m.id),
      roomId: m.room_id, storageLocation: m.storage_location,
      snapshotUrl: snap, sourceBadge: `Calibrated AI (${Math.round(topCand.score * 100)}%)`
    };
  } else if (topCand && topCand.rawClass && topCand.score >= state.arConfidenceThreshold) {
    const detName = topCand.rawClass.charAt(0).toUpperCase() + topCand.rawClass.slice(1);
    state.arDetectedObject = {
      existingObjectId: null, name: detName, category: "Personal belongings",
      textCode: generateTextCode(detName), roomId: rooms[0] ? rooms[0].id : null,
      storageLocation: "Recorded via AR Camera", snapshotUrl: snap,
      sourceBadge: `AI Detected (${Math.round(topCand.score * 100)}%)`
    };
  } else if (targetObj) {
    state.arDetectedObject = {
      existingObjectId: targetObj.id, name: targetObj.name, category: targetObj.category,
      textCode: targetObj.text_code || generateTextCode(targetObj.name, targetObj.id),
      roomId: targetObj.room_id, storageLocation: targetObj.storage_location,
      snapshotUrl: snap, sourceBadge: "Camera Snapshot + Code"
    };
  }
  stopARCamera();
  render();
  showToast("Captured frame! Confirm details and tap Save to also train the AI.");
}

async function runAIObjectDetectionOnImage(dataUrl, filename) {
  const rooms = getActiveRooms();
  const img = new Image();
  img.onload = async () => {
    await ensureARVisionModel();
    const res = await runCalibratedInference(img, false);
    if (res.matchedObj) {
      const m = res.matchedObj;
      state.arDetectedObject = {
        existingObjectId: m.id, name: m.name, category: m.category,
        textCode: m.text_code || generateTextCode(m.name, m.id),
        roomId: m.room_id, storageLocation: m.storage_location,
        snapshotUrl: dataUrl, sourceBadge: `${res.source} (${Math.round(res.score * 100)}%) + Code`
      };
      render();
      speakText(`Found! Your ${m.name}, code ${m.text_code}, was identified with ${Math.round(res.score * 100)} percent confidence.`);
    } else if (res.label) {
      const detName = res.label.charAt(0).toUpperCase() + res.label.slice(1);
      state.arDetectedObject = {
        existingObjectId: null, name: detName, category: "Personal belongings",
        textCode: generateTextCode(detName), roomId: rooms[0] ? rooms[0].id : null,
        storageLocation: "Scanned via AR AI", snapshotUrl: dataUrl,
        sourceBadge: `${res.source} (${Math.round(res.score * 100)}%)`
      };
      render();
      speakText(`Detected ${detName}. Confirm and tap Save to teach the AI this object.`);
    } else {
      const sug = suggestObjectFromFilenameOrHint(filename, "");
      const name = sug.name || "Household item";
      state.arDetectedObject = {
        existingObjectId: null, name, category: sug.category,
        textCode: generateTextCode(name), roomId: rooms[0] ? rooms[0].id : null,
        storageLocation: "Scanned spot", snapshotUrl: dataUrl,
        sourceBadge: "Uncertain — Label to Train AI"
      };
      render();
      showToast("AI wasn't 100% sure—enter the name and tap Save to train the AI on it!", "info");
    }
  };
  img.src = dataUrl;
}

function startARCamera() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    showToast("Camera API unavailable here. Use 'Scan Photo' or tap any saved object on the right.", "info");
    return;
  }
  ensureARVisionModel();
  navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } }).then(stream => {
    state.arStream = stream;
    state.arCameraActive = true;
    state.arDetectedObject = null;
    state.arStabilityBuffer = [];
    render();
    const vid = document.getElementById("arVideo");
    if (!vid) return;
    vid.srcObject = stream;
    vid.play();
    const scanCanvas = document.createElement("canvas");
    const scanCtx = scanCanvas.getContext("2d", { willReadFrequently: true });

    const tick = () => {
      if (!state.arCameraActive) return;
      const overlay = document.getElementById("arOverlayCanvas");
      if (vid.readyState === vid.HAVE_ENOUGH_DATA && overlay) {
        scanCanvas.width = vid.videoWidth;
        scanCanvas.height = vid.videoHeight;
        overlay.width = vid.videoWidth;
        overlay.height = vid.videoHeight;
        scanCtx.drawImage(vid, 0, 0, scanCanvas.width, scanCanvas.height);
        const octx = overlay.getContext("2d");
        octx.clearRect(0, 0, overlay.width, overlay.height);

        // 1. Calibrated Multi-Model Inference (every 650ms, skipping during burst training)
        const nowMs = Date.now();
        if (!state.arAutoTraining && (state.arCocoModel || state.arMobileNetModel) && nowMs - state.arLastDetectTs > 650) {
          state.arLastDetectTs = nowMs;
          runCalibratedInference(vid, true).then(res => {
            state.arLiveDetections = res.cocoDetections || [];
            const key = res.matchedObj ? ("obj_" + res.matchedObj.id) : (res.label ? ("raw_" + res.label) : "none");
            state.arStabilityBuffer.push(key);
            if (state.arStabilityBuffer.length > 3) state.arStabilityBuffer.shift();
            const isStable = state.arStabilityBuffer.length === 3 && state.arStabilityBuffer.every(k => k === key) && key !== "none";

            if (isStable && res.matchedObj) {
              const m = res.matchedObj;
              let dirHint = "right in front of you";
              if (res.bbox) {
                const cr = (res.bbox[0] + res.bbox[2] / 2) / Math.max(1, overlay.width);
                dirHint = cr < 0.35 ? "to your left" : cr > 0.65 ? "to your right" : "right in front of you";
              }
              updateARLivePromptDOM(`FOUND! ${m.name} [${m.text_code}] (${Math.round(res.score * 100)}%) — ${dirHint}`, true);
              speakARPromptThrottled("stable_" + m.id, `It has been found! Your ${m.name}, code ${m.text_code}, is ${dirHint}.`);
            } else if (isStable && res.label) {
              updateARLivePromptDOM(`Detected: ${res.label} (${Math.round(res.score * 100)}%) — Tap Capture & Save`, false);
              speakARPromptThrottled("raw_" + res.label, `Detected ${res.label}. Tap Capture and Save to teach the AI.`);
            } else if (key === "none") {
              updateARLivePromptDOM("Hold steady — center object or QR code in box", false);
            }
          }).catch(() => {});
        }

        // Draw Calibrated COCO-SSD Bounding Boxes
        state.arLiveDetections.forEach(p => {
          const [bx, by, bw, bh] = p.bbox;
          const matched = matchDetectionToSavedObject(p.class);
          const labelText = matched
            ? `${matched.name} [${matched.text_code}] (${Math.round(p.score * 100)}%)`
            : `${p.class} (${Math.round(p.score * 100)}%)`;
          octx.strokeStyle = matched ? "#10B981" : "#3B82F6";
          octx.lineWidth = 4;
          octx.strokeRect(bx, by, bw, bh);
          octx.fillStyle = matched ? "#047857" : "#1D4ED8";
          const tw = Math.min(overlay.width - bx, labelText.length * 9 + 18);
          octx.fillRect(bx, Math.max(0, by - 28), tw, 26);
          octx.fillStyle = "#FFFFFF";
          octx.font = "bold 14px Inter, sans-serif";
          octx.fillText(labelText, bx + 8, Math.max(18, by - 10));
        });

        // 2. Simultaneous QR / Visual Code Recognition (jsQR)
        if (window.jsQR) {
          const imgData = scanCtx.getImageData(0, 0, scanCanvas.width, scanCanvas.height);
          const code = window.jsQR(imgData.data, imgData.width, imgData.height, { inversionAttempts: "dontInvert" });
          if (code && code.data) {
            const loc = code.location;
            octx.strokeStyle = "#10B981";
            octx.lineWidth = 6;
            octx.beginPath();
            octx.moveTo(loc.topLeftCorner.x, loc.topLeftCorner.y);
            octx.lineTo(loc.topRightCorner.x, loc.topRightCorner.y);
            octx.lineTo(loc.bottomRightCorner.x, loc.bottomRightCorner.y);
            octx.lineTo(loc.bottomLeftCorner.x, loc.bottomLeftCorner.y);
            octx.closePath();
            octx.stroke();

            if (!state.arMatchedMarker || (state.arMatchedMarker.marker_reference !== code.data && state.arMatchedMarker.text_code !== code.data)) {
              triggerARMarkerMatch(code.data);
            }
          }
        }
      }
      state.arAnimFrame = requestAnimationFrame(tick);
    };
    state.arAnimFrame = requestAnimationFrame(tick);
  }).catch(() => {
    showToast("Camera permission denied or unavailable. Use 'Scan Photo' or tap any object on the right.", "warn");
  });
}

function triggerARMarkerMatch(codeInput) {
  const cleaned = String(codeInput || "").trim().toUpperCase();
  if (!cleaned) return;
  const uid = getActiveUserId();
  const m = DB.ar_markers.find(
    x => x.user_id === uid && (
      String(x.marker_reference || "").toUpperCase() === cleaned ||
      String(x.text_code || "").toUpperCase() === cleaned
    )
  );
  const obj = m
    ? getActiveObjects().find(o => o.id === m.object_id)
    : getActiveObjects().find(o => String(o.text_code || "").toUpperCase() === cleaned);

  if (!obj) {
    showToast(`Code "${cleaned}" is not assigned to any saved object yet.`, "warn");
    return;
  }
  state.arMatchedMarker = m || {
    marker_reference: cleaned, text_code: obj.text_code, object_id: obj.id,
    associated_location: `${getRoomName(obj.room_id)} — ${obj.storage_location}`
  };
  state.arTargetObjectId = obj.id;
  state.arDetectedObject = {
    existingObjectId: obj.id, name: obj.name, category: obj.category,
    textCode: obj.text_code || cleaned, roomId: obj.room_id,
    storageLocation: obj.storage_location, snapshotUrl: obj.image_url || SVG_PLACEHOLDERS.defaultObj,
    sourceBadge: `Code Matched: ${obj.text_code || cleaned}`
  };
  render();
  speakText(`Code ${obj.text_code || cleaned} recognised. Your ${obj.name.toLowerCase()} is kept in the ${getRoomName(obj.room_id)} at ${obj.storage_location}.`);
}

function renderAllQRCodes() {
  if (typeof window.qrcode !== "function") return;
  DB.ar_markers.filter(m => m.user_id === getActiveUserId()).forEach(m => {
    const el = document.getElementById("qr_" + m.id);
    if (!el) return;
    const qr = window.qrcode(0, "M");
    qr.addData(m.text_code || m.marker_reference);
    qr.make();
    el.innerHTML = qr.createSvgTag(3, 2);
  });
}

function printMarkerCard(markerId) {
  const m = DB.ar_markers.find(x => x.id === Number(markerId));
  if (!m) return;
  const o = getActiveObjects().find(x => x.id === m.object_id);
  const qrEl = document.getElementById("qr_" + m.id);
  const svgHtml = qrEl ? qrEl.innerHTML : "";
  const displayCode = m.text_code || (o && o.text_code) || m.marker_reference;
  openModal(`
    <div class="text-center space-y-3">
      <div class="text-xs font-bold uppercase text-blue-700">Printable Image + Text Code AR Tag</div>
      <div class="p-4 border-2 border-dashed border-slate-400 rounded-2xl inline-block bg-white">
        <div class="font-extrabold text-lg text-slate-900">${esc(o ? o.name : "Household Location")}</div>
        <div class="text-xs text-slate-600 mb-2">${esc(m.associated_location)}</div>
        <div class="flex items-center justify-center gap-3">
          <img src="${(o && o.image_url) || SVG_PLACEHOLDERS.defaultObj}" alt="" class="w-24 h-24 rounded-xl object-cover border border-slate-200" />
          <div>${svgHtml}</div>
        </div>
        <div class="font-mono text-base font-extrabold text-blue-800 mt-2 tracking-wider">${esc(displayCode)}</div>
      </div>
      <p class="text-xs text-slate-600">Place this tag near the drawer, shelf, or table so the AR camera can recognize both the QR code and text code alongside the object image.</p>
      <div class="flex justify-center gap-2 pt-2">
        <button type="button" onclick="window.print()" class="btn-primary px-5 py-2.5 rounded-xl bg-blue-700 text-white font-bold text-sm">Print Now</button>
        <button type="button" onclick="closeModal()" class="px-4 py-2.5 rounded-xl border border-slate-200 font-semibold text-sm">Close</button>
      </div>
    </div>
  `);
}

function deleteARMarker(markerId) {
  DB.ar_markers = DB.ar_markers.filter(m => m.id !== Number(markerId));
  saveDB();
  render();
  showToast("AR marker removed.");
}

